import type { EnemyContext, VictoryContext, Vec2 } from './rule-types';

export function getEnemyVelocity(context: EnemyContext): Vec2 {
  if (context.behavior === 'chase' || context.behavior === 'guard') {
    const dx = context.player.x - context.enemy.x;
    const dy = context.player.y - context.enemy.y;
    const distance = Math.hypot(dx, dy);
    if (distance === 0) return { x: 0, y: 0 };
    if (context.behavior === 'guard' && distance > 180) return { x: 0, y: 0 };
    return { x: dx / distance * context.speed, y: dy / distance * context.speed };
  }
  if (context.behavior === 'vertical-patrol') {
    if (context.enemy.y >= context.bounds.maxY) return { x: 0, y: -context.speed };
    if (context.enemy.y <= context.bounds.minY) return { x: 0, y: context.speed };
    return { x: 0, y: context.enemy.vy < 0 ? -context.speed : context.speed };
  }
  if (context.enemy.x >= context.bounds.maxX) return { x: -context.speed, y: 0 };
  if (context.enemy.x <= context.bounds.minX) return { x: context.speed, y: 0 };
  return { x: context.enemy.vx < 0 ? -context.speed : context.speed, y: 0 };
}

export function isVictory(context: VictoryContext): boolean {
  if (context.mode === 'survive-then-exit') return context.elapsedTicks >= context.survivalTicks && context.atExit;
  const enough = context.score >= context.target;
  return context.mode === 'collect-all' ? enough : enough && context.atExit;
}
